<!DOCTYPE html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><title>Profile | AppTasker</title><style>body{margin:0;background:#f5f7fb;font-family:Inter,system-ui;color:#182230}.w{max-width:800px;margin:auto;padding:24px 16px}.back{color:#526df5;text-decoration:none;font-weight:800}.card{background:#fff;border:1px solid #e7eaf0;border-radius:20px;padding:24px;margin-top:20px}.avatar{width:70px;height:70px;border-radius:50%;display:grid;place-items:center;background:#eef1ff;color:#526df5;font-size:28px;font-weight:900}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.stat{background:#f8f9fc;padding:16px;border-radius:14px}.stat small{color:#667085}.stat strong{display:block;font-size:22px}@media(max-width:520px){.grid{grid-template-columns:1fr}}</style></head><body><main class="w"><a class="back" href="{{ route('worker.dashboard') }}">← Dashboard</a><section class="card"><div class="avatar">{{ strtoupper(substr(auth()->user()->name,0,1)) }}</div><h1>{{ auth()->user()->name }}</h1><p>{{ auth()->user()->email }}</p><div class="grid"><div class="stat"><small>Trust Level</small><strong>{{ $trustLevel }}</strong></div><div class="stat"><small>Approved</small><strong>{{ $approved }}</strong></div><div class="stat"><small>Rejected</small><strong>{{ $rejected }}</strong></div></div></section></main></body></html>